The Shiny Mental Model
Understanding three core concepts is essential:

1. User Interface (UI)
The frontend that users see and interact with:
from shiny import ui

app_ui = ui.page_fluid(
    ui.h2("Auckland Pedestrian Dashboard"),
    ui.input_slider("hour", "Hour of Day", 0, 23, 12),
    ui.output_plot("hourly_plot")
)
The UI defines: - Layout and structure - Input controls (sliders, dropdowns, date pickers) - Output placeholders (maps, plots, tables)


2. Server Function
The backend that processes data and generates outputs:
def server(input, output, session):
    @output
    @render.plot
    def hourly_plot():
        # This code runs reactively when input.hour() changes
        filtered_data = data[data['hour'] == input.hour()]
        return create_plot(filtered_data)
The server: - Reads input values - Performs calculations and analysis - Generates outputs (plots, tables, maps)


3. Reactivity
The magic that connects inputs to outputs:
@reactive.Calc
def filtered_data():
    # Recalculates automatically when inputs change
    return data[data['hour'] == input.hour()]

@output
@render.table
def summary_table():
    # Uses the reactive calculation
    df = filtered_data()
    return df.describe()
Reactivity ensures: - Outputs update automatically when inputs change - Only necessary calculations are performed - Multiple outputs can depend on the same reactive calculation

5.3 The Shiny Architecture

5.3.1 Three-Layer Model
Every Shiny application has three components:
from shiny import App, ui

# 1. UI: What users see
app_ui = ui.page_fluid(
    ui.h2("My Dashboard"),
    ui.input_slider("value", "Select", 0, 100, 50),
    ui.output_text("result")
)

# 2. Server: What happens behind the scenes
def server(input, output, session):
    @output
    @render.text
    def result():
        return f"You selected: {input.value()}"

# 3. App: Combining UI and server
app = App(app_ui, server)


5.3.2 Key Principles
1. Load Data Once
# Load outside server function - happens once at startup
regions = gpd.read_file('data/auckland_sa2.gpkg')

def server(input, output, session):
    # Data already loaded - use it here
    pass
2. Use Pure Functions for Transformations
def calculate_density(gdf, pop_column='population'):
    """Pure function: same inputs → same outputs"""
    gdf = gdf.copy()
    gdf['area_km2'] = gdf.geometry.area / 1_000_000
    gdf['density'] = gdf[pop_column] / gdf['area_km2']
    return gdf

# Use in server
def server(input, output, session):
    @reactive.Calc
    def processed_data():
        return calculate_density(regions)
3. Use Reactives for Filtered Views
@reactive.Calc
def filtered_regions():
    """Reactive calculation: updates when inputs change"""
    selected = input.region_filter()
    return regions[regions['SA2_name'].isin(selected)]

5.4 Understanding Reactivity

5.4.1 The Reactive Graph
Shiny automatically tracks dependencies between inputs, calculations, and outputs:
[Input: region_filter] ──→ [@reactive.Calc: filtered_regions] ──→ [Output: map]
                      ──→                                       ──→ [Output: table]
When region_filter changes: 1. filtered_regions() recalculates automatically 2. Both map and table outputs update 3. Other unaffected outputs remain unchanged


5.4.2 Reactive Building Blocks
1. Inputs - User controls
app_ui = ui.page_fluid(
    # Text input
    ui.input_text("location", "Location Name", "Auckland CBD"),

    # Numeric slider
    ui.input_slider("radius", "Radius (km)", 1, 20, 5),

    # Select dropdown
    ui.input_select(
        "indicator",
        "Choose Indicator",
        choices=["Population", "Income", "Age"]
    ),

    # Multiple selection
    ui.input_selectize(
        "regions",
        "Select Regions",
        choices=region_names,
        multiple=True
    ),

    # Date input
    ui.input_date("start_date", "Start Date"),

    # Checkbox
    ui.input_checkbox("include_weekends", "Include Weekends", True),

    # Radio buttons
    ui.input_radio_buttons(
        "time_period",
        "Time Period",
        choices=["Morning", "Afternoon", "Evening"]
    )
)
2. Reactive Calculations - Shared computations
def server(input, output, session):

    @reactive.Calc
    def base_data():
        """Load and process base data"""
        gdf = gpd.read_file('data/regions.gpkg')
        return calculate_density(gdf)

    @reactive.Calc
    def filtered_data():
        """Filter based on user inputs - depends on base_data"""
        data = base_data()  # Uses reactive
        selected = input.regions()
        return data[data['name'].isin(selected)]

    @reactive.Calc
    def summary_stats():
        """Calculate statistics - depends on filtered_data"""
        data = filtered_data()  # Uses another reactive
        return {
            'count': len(data),
            'mean_density': data['density'].mean(),
            'total_pop': data['population'].sum()
        }
3. Outputs - What users see
@output
@render.plot
def density_map():
    """Render matplotlib plot"""
    data = filtered_data()
    fig, ax = plt.subplots()
    data.plot(column='density', ax=ax, legend=True)
    return fig

@output
@render.table
def summary_table():
    """Render pandas DataFrame"""
    return filtered_data()[['name', 'population', 'density']]

@output
@render.text
def stats_text():
    """Render formatted text"""
    stats = summary_stats()
    return f"Selected {stats['count']} regions with mean density {stats['mean_density']:.1f}"

@output
@render.ui
def dynamic_controls():
    """Render dynamic UI elements"""
    data = base_data()
    choices = data['name'].tolist()
    return ui.input_selectize("regions", "Regions", choices=choices, multiple=True)

5.6 Advanced Reactive Patterns

5.6.1 Pattern 1: Debouncing Rapid Changes
Prevent excessive recalculation when inputs change rapidly:
@reactive.Calc
def filtered_data():
    """Only recalculate after user stops adjusting slider"""
    with reactive.isolate():
        # Wait until user finishes moving slider
        min_val = input.min_value()
    return data[data['value'] &gt;= min_val]


5.6.2 Pattern 2: Conditional Reactivity
Only trigger updates when relevant inputs change:
@reactive.Effect
@reactive.event(input.update_button)  # Only run when button clicked
def update_data():
    """Manual update triggered by button"""
    new_data = fetch_fresh_data()
    # Process and update


5.6.3 Pattern 3: Reactive Values
Create reactive values that can be programmatically updated:
from shiny import reactive

def server(input, output, session):
    # Create a reactive value
    selected_features = reactive.Value([])

    @reactive.Effect
    @reactive.event(input.map_click)
    def handle_click():
        """Update selected features when map is clicked"""
        current = selected_features()
        current.append(input.map_click())
        selected_features.set(current)

    @output
    @render.text
    def selection_count():
        return f"Selected {len(selected_features())} features"


5.6.4 Pattern 4: Progress Indicators
Show progress for long-running operations:
from shiny import ui

@output
@render.plot
async def complex_analysis():
    """Show progress during computation"""
    with ui.Progress(min=0, max=100) as progress:
        progress.set(message="Loading data")
        data = load_large_dataset()

        progress.set(50, message="Processing")
        result = expensive_calculation(data)

        progress.set(100, message="Rendering")
        return create_plot(result)

5.7 Performance Optimisation

5.7.1 Strategy 1: Cache Expensive Calculations
from functools import lru_cache

@lru_cache(maxsize=128)
def calculate_network_centrality(location, radius):
    """Cache results for common parameter combinations"""
    graph = ox.graph_from_point(location, dist=radius)
    return nx.betweenness_centrality(graph)

def server(input, output, session):
    @reactive.Calc
    def centrality():
        loc = (input.lat(), input.lon())
        return calculate_network_centrality(loc, input.radius())


5.7.2 Strategy 2: Pre-Process Data
# Outside server function - runs once
data = gpd.read_file('large_dataset.gpkg')
data = data.to_crs('EPSG:4326')  # Reproject once
data['area'] = data.geometry.area  # Calculate once

# Simplify geometries for faster rendering
data['geometry'] = data.geometry.simplify(0.001)


5.7.3 Strategy 3: Lazy Loading
@reactive.Calc
def expensive_data():
    """Only load when actually needed"""
    if not input.show_detailed_view():
        return None  # Don't load if not viewing

    return load_detailed_dataset()

@output
@render.plot
def detailed_map():
    data = expensive_data()
    if data is None:
        return simple_overview_plot()
    return detailed_plot(data)

5.9 Testing and Debugging

5.9.1 Print Reactive Values
@reactive.Effect
def _():
    """Debug reactive values"""
    print(f"Current selection: {input.regions()}")
    print(f"Filtered count: {len(filtered_data())}")


5.9.2 Validate Inputs
@reactive.Calc
def validated_radius():
    """Ensure input is within valid range"""
    radius = input.radius()
    if radius &lt; 1:
        return 1
    elif radius &gt; 50:
        return 50
    return radius


5.9.3 Error Handling
@output
@render.plot
def safe_map():
    """Handle errors gracefully"""
    try:
        data = filtered_data()
        if len(data) == 0:
            return empty_plot_message("No data")
        return create_map(data)
    except Exception as e:
        print(f"Error creating map: {e}")
        return error_plot(str(e))

7.7 Dashboard Integration

7.7.1 OD Analysis Dashboard
from shiny import App, ui, render, reactive
import pandas as pd
import matplotlib.pyplot as plt

# Load OD data
od_matrix = pd.read_csv('od_matrix.csv', index_col=0)

app_ui = ui.page_fluid(
    ui.h2("Auckland Origin-Destination Analysis"),

    ui.layout_sidebar(
        ui.panel_sidebar(
            ui.input_slider(
                "min_flow",
                "Minimum Flow to Display",
                min=0,
                max=500,
                value=100,
                step=50
            ),

            ui.input_select(
                "viz_type",
                "Visualisation Type",
                choices=["Matrix", "Chord", "Desire Lines"]
            ),

            ui.hr(),
            ui.h4("Summary"),
            ui.output_text_verbatim("summary_stats")
        ),

        ui.panel_main(
            ui.navset_tab(
                ui.nav("Visualisation", ui.output_plot("od_viz")),
                ui.nav("Top Pairs", ui.output_table("top_pairs")),
                ui.nav("Zone Stats", ui.output_table("zone_stats"))
            )
        )
    )
)

def server(input, output, session):

    @reactive.Calc
    def filtered_od():
        """Filter OD matrix by minimum flow"""
        threshold = input.min_flow()
        return od_matrix[od_matrix &gt;= threshold].fillna(0)

    @output
    @render.plot
    def od_viz():
        """Create selected visualisation"""
        od = filtered_od()
        viz_type = input.viz_type()

        if viz_type == "Matrix":
            fig, ax = plt.subplots(figsize=(10, 8))
            im = ax.imshow(od, cmap='YlOrRd')
            ax.set_xticks(range(len(od.columns)))
            ax.set_yticks(range(len(od.index)))
            ax.set_xticklabels(od.columns, rotation=45)
            ax.set_yticklabels(od.index)
            plt.colorbar(im, ax=ax, label='Trips')
            ax.set_title('OD Matrix')

        elif viz_type == "Chord":
            fig, ax = plot_od_chord(od, threshold=input.min_flow())

        else:  # Desire Lines
            fig, ax = plot_desire_lines(od, zones_gdf, threshold=input.min_flow())

        return fig

    @output
    @render.text
    def summary_stats():
        """Display summary statistics"""
        stats = analyse_od_matrix(od_matrix)
        return f"""
Total Trips: {stats['total_trips']:,.0f}

Intra-zonal: {stats['intra_zonal']:,.0f} ({stats['intra_pct']:.1f}%)
Inter-zonal: {stats['inter_zonal']:,.0f}

Filtered (≥{input.min_flow()}): {filtered_od().sum().sum():,.0f}
        """.strip()

    @output
    @render.table
    def top_pairs():
        """Show top OD pairs"""
        stats = analyse_od_matrix(od_matrix)
        return stats['top_pairs']

    @output
    @render.table
    def zone_stats():
        """Show zone-level statistics"""
        return calculate_production_attraction(od_matrix)

app = App(app_ui, server)
